Basic Admin Page:
```tsx
import { AdminPageTemplate, Button } from '@/lib/designsystem';
import { Plus } from 'lucide-react';

export default function GalleriesPage() {
  return (
    <AdminPageTemplate
      title="Galleries"
      actions={
        <Button variant="primary" Icon={Plus}>
          New Gallery
        </Button>
      }
    >
      {/* Page content */}
    </AdminPageTemplate>
  );
}
```

Detail Page with Back Button and Status:
```tsx
import { AdminPageTemplate, Tag, Button } from '@/lib/designsystem';
import { useRouter } from 'next/navigation';

export default function AnalysisDetailPage() {
  const router = useRouter();

  return (
    <AdminPageTemplate
      title="image-filename.jpg"
      onBackClick={() => router.back()}
      status={<Tag variant="success">Approved</Tag>}
      actions={
        <Button variant="secondary">Re-analyze</Button>
      }
    >
      {/* Detail content */}
    </AdminPageTemplate>
  );
}
```

Top-Level Section with ASCII Title:
```tsx
import { AdminPageTemplate, Button } from '@/lib/designsystem';
import { FolderOpen, Sparkles, Plus } from 'lucide-react';

export default function PhotosPage() {
  return (
    <AdminPageTemplate
      title="Photos"
      asciiTitle="Photos"
      actions={
        <>
          <Button Icon={FolderOpen}>Image Manager</Button>
          <Button Icon={Sparkles}>Analyze Photos</Button>
          <Button variant="primary" Icon={Plus}>New Gallery</Button>
        </>
      }
    >
      {/* Gallery grid */}
    </AdminPageTemplate>
  );
}
```

Page with Loading State:
```tsx
<AdminPageTemplate
  title="Analysis Details"
  onBackClick={() => router.back()}
  loading={isLoading}
>
  {/* Content only renders when loading is false */}
</AdminPageTemplate>
```

Page with Error State:
```tsx
<AdminPageTemplate
  title="Analysis Details"
  onBackClick={() => router.back()}
  error={error}
>
  {/* Content only renders when error is null */}
</AdminPageTemplate>
```
